functions.q:
Программа нені шығарады?
def f(x):
    if x > 0:
        return "оң"
    return "оң емес"
print(f(0))

Программа нені шығарады?
def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)
print(fact(5))

Программа нені шығарады?
def f(n):
    if n == 0:
        return 0
    return n % 10 + f(n // 10)
print(f(507))

Программа нені шығарады?
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)
print(fib(7))

Программа нені шығарады?
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
print(gcd(48, 18))

Программа нені шығарады?
def f(n):
    return 1 if n == 0 else 2 * f(n - 1)
print(f(5))

